import React from 'react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { screen } from '@testing-library/react';
import { render, createMockFetch } from './setup';
import type { FieldMetadata } from '../src/hooks/use-entities';

/**
 * The grid's columns, as `/sys/fields` describes them — the first entity of
 * this application's own model, one string column per attribute. Passing them
 * in keeps these tests about the table rather than about the fetch.
 */
const GRID_TABLE = 'bus_party';
const GRID_COLUMNS: string[] = [
  'id',
  'party_type',
  'display_name',
  'status',
  'external_reference',
  'person_id',
  'organization_id',
];
const GRID_FIELDS: FieldMetadata[] = GRID_COLUMNS.map((column, index) => ({
  sys_field_id: `field-${column}`,
  name: column,
  column_name: column,
  sys_reference_id: 10,
  is_mandatory: false,
  seq_no: (index + 1) * 10,
  seq_no_grid: (index + 1) * 10,
  is_displayed: true,
  is_displayed_grid: true,
  is_read_only: false,
}));

function gridRow(n: number): Record<string, unknown> {
  return Object.fromEntries([
    ['id', `row-${n}`],
    ...GRID_COLUMNS.filter((c) => c !== 'id').map((c) => [c, `${c} ${n}`]),
  ]);
}

describe('DynamicTable Component', () => {
  it('draws the loading skeleton while the rows are loading', async () => {
    const { DynamicTable } = await import('../src/components/tables/dynamic-table');
    const { container } = render(
      <DynamicTable tableName={GRID_TABLE} fields={GRID_FIELDS} data={[]} isLoading={true} totalCount={0} />
    );
    expect(container.querySelector('[data-testid="table-loading-skeleton"]')).toBeTruthy();
  });

  it('renders one row per record, under one header per displayed column', async () => {
    const { DynamicTable } = await import('../src/components/tables/dynamic-table');
    const { container } = render(
      <DynamicTable
        tableName={GRID_TABLE}
        fields={GRID_FIELDS}
        data={[gridRow(1), gridRow(2)]}
        isLoading={false}
        totalCount={2}
      />
    );
    const table = container.querySelector('[data-testid="entity-table"]');
    expect(table).toBeTruthy();
    expect(table?.querySelectorAll('tbody tr')).toHaveLength(2);
    expect(container.querySelector('[data-testid="no-results-row"]')).toBeNull();
  });

  it('says there are no results when there are no records', async () => {
    const { DynamicTable } = await import('../src/components/tables/dynamic-table');
    const { container } = render(
      <DynamicTable tableName={GRID_TABLE} fields={GRID_FIELDS} data={[]} isLoading={false} totalCount={0} />
    );
    expect(container.querySelector('[data-testid="no-results-row"]')).toBeTruthy();
  });

  it('reports which records of the total are on screen', async () => {
    const { DynamicTable } = await import('../src/components/tables/dynamic-table');
    render(
      <DynamicTable
        tableName={GRID_TABLE}
        fields={GRID_FIELDS}
        data={[gridRow(1)]}
        isLoading={false}
        totalCount={10}
      />
    );
    expect(screen.getByText(/Showing 1 to 10 of\s*10 entries/)).toBeTruthy();
  });

  it('says so when the dictionary configures no grid columns', async () => {
    const { DynamicTable } = await import('../src/components/tables/dynamic-table');
    render(<DynamicTable tableName={GRID_TABLE} fields={[]} data={[]} isLoading={false} />);
    expect(screen.getByText('No columns configured for grid display.')).toBeTruthy();
  });
});

describe('API Mock Utilities', () => {
  it('createMockFetch returns 200 for known paths', async () => {
    const mockFetch = createMockFetch({
      '/bus/test_table': { data: [], meta: { total: 0 } },
    });

    const response = await mockFetch('/bus/test_table');
    expect(response.ok).toBe(true);
    expect(response.status).toBe(200);
  });

  it('createMockFetch returns 404 for unknown paths', async () => {
    const mockFetch = createMockFetch({});
    const response = await mockFetch('/api/unknown');
    expect(response.status).toBe(404);
  });

  it('createMockFetch returns correct response body', async () => {
    const testData = { data: [{ id: '1', name: 'Test' }] };
    const mockFetch = createMockFetch({
      '/api/test': testData,
    });

    const response = await mockFetch('/api/test');
    const body = await response.json();
    expect(body).toEqual(testData);
  });
});
